import { createHash } from 'node:crypto'
import { mkdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { test, expect, workspace } from './fixtures'
import { createQmcCipher, decryptQmcChunk } from '../src/features/music/algorithms'

// Synthetic QMC test vector generated by the uNAS test helper; it is not an
// upstream fixture or a user key. The derived key is a 30-byte map cipher.
const EKEY = 'dU5BUy1FSzGCzjmFvnGs92deDVCxcu74GR7w6PhN8HMcFTbUKgQ5ig=='
const MEDIA_FILE_NAME = 'sample.mflac'
const TAG_BYTES = 0xc0
const SALT_BYTES = 0x48
const NAME_BYTES = 100

function writeUint32LE(bytes: Uint8Array, offset: number, value: number) {
  bytes[offset] = value & 0xff
  bytes[offset + 1] = value >>> 8 & 0xff
  bytes[offset + 2] = value >>> 16 & 0xff
  bytes[offset + 3] = value >>> 24 & 0xff
}

function buildMusicExTag(mediaFileName: string) {
  const tag = new Uint8Array(TAG_BYTES)
  for (let index = 0; index < mediaFileName.length && index < NAME_BYTES / 2; index += 1) tag[SALT_BYTES + index * 2] = mediaFileName.charCodeAt(index)
  writeUint32LE(tag, TAG_BYTES - 16, TAG_BYTES)
  writeUint32LE(tag, TAG_BYTES - 12, 1)
  tag.set(new TextEncoder().encode('musicex\0'), TAG_BYTES - 8)
  return tag
}

function buildEncryptedAudio(plain: Uint8Array) {
  const cipher = createQmcCipher(new TextEncoder().encode(EKEY))
  return decryptQmcChunk(plain, cipher, 0)
}

function buildSample(plain: Uint8Array, footer: 'musicex' | 'legacy') {
  const encrypted = buildEncryptedAudio(plain)
  if (footer === 'legacy') {
    const result = new Uint8Array(encrypted.length + 4)
    result.set(encrypted)
    return result
  }
  const tag = buildMusicExTag(MEDIA_FILE_NAME)
  const result = new Uint8Array(encrypted.length + tag.length)
  result.set(encrypted)
  result.set(tag, encrypted.length)
  return result
}

function makePlain() {
  const plain = new Uint8Array(4096)
  plain.set(new TextEncoder().encode('fLaC'))
  for (let index = 4; index < plain.length; index += 1) plain[index] = index * 31 & 0xff
  return plain
}

function writeInputs(fixtureName: string, plain: Uint8Array, footer: 'musicex' | 'legacy', manifest: unknown) {
  const directory = test.info().outputPath()
  mkdirSync(directory, { recursive: true })
  const samplePath = path.join(directory, fixtureName)
  const keyPath = path.join(directory, 'keys.json')
  writeFileSync(samplePath, buildSample(plain, footer))
  writeFileSync(keyPath, JSON.stringify(manifest))
  return { samplePath, keyPath }
}

async function selectFiles(page: import('@playwright/test').Page, samplePath: string, keyPath?: string) {
  const app = page.locator('[data-app-id="music"]')
  const inputs = app.locator('input[type="file"]')
  await expect(inputs).toHaveCount(2)
  await inputs.nth(0).setInputFiles(samplePath)
  if (keyPath) await inputs.nth(1).setInputFiles(keyPath)
  return app
}

test('imported ekey decrypts a QMC musicex file locally and reports the key source', async ({ extension }) => {
  const plain = makePlain()
  const { samplePath, keyPath } = writeInputs('musicex.mflac', plain, 'musicex', { [MEDIA_FILE_NAME]: EKEY })
  const page = await workspace(extension, 'music')
  const app = await selectFiles(page, samplePath, keyPath)
  await expect(app.getByText('Worker READY')).toBeVisible()
  await expect(app.locator('input[type="file"]').nth(0)).toHaveAttribute('accept', /\.mflac2/)
  await expect(app).toContainText('keys.json')

  await app.getByRole('button', { name: '开始解密', exact: true }).click()
  await expect(app.locator('.music-app__result strong')).toHaveText('FLAC 音频签名已识别', { timeout: 20_000 })
  await expect(app).toContainText('导入的 ekey')
  await expect(app.locator('[data-output-sha256]')).toHaveAttribute('data-output-sha256', createHash('sha256').update(plain).digest('hex'))
  expect(extension.remoteRequests).toEqual([])
  expect(extension.errors).toEqual([])
  await app.getByRole('button', { name: '清理暂存', exact: true }).click()
})

test('imported ekey decrypts a keyless legacy QMC file by its selected name', async ({ extension }) => {
  const plain = makePlain()
  const { samplePath, keyPath } = writeInputs('legacy.mflac', plain, 'legacy', { 'legacy.mflac': EKEY })
  const page = await workspace(extension, 'music')
  const app = await selectFiles(page, samplePath, keyPath)

  await app.getByRole('button', { name: '开始解密', exact: true }).click()
  await expect(app.locator('.music-app__result strong')).toHaveText('FLAC 音频签名已识别', { timeout: 20_000 })
  await expect(app).toContainText('导入的 ekey')
  expect(extension.remoteRequests).toEqual([])
  expect(extension.errors).toEqual([])
  await app.getByRole('button', { name: '清理暂存', exact: true }).click()
})

test('musicex without a matching ekey fails before producing output', async ({ extension }) => {
  const plain = makePlain()
  const { samplePath } = writeInputs('missing.mflac', plain, 'musicex', {})
  const page = await workspace(extension, 'music')
  const app = await selectFiles(page, samplePath)

  await app.getByRole('button', { name: '开始解密', exact: true }).click()
  await expect(app.locator('.music-app__error')).toContainText('需要匹配的 ekey', { timeout: 10_000 })
  await expect(app.getByRole('button', { name: '下载解密结果', exact: true })).toHaveCount(0)
  expect(extension.remoteRequests).toEqual([])
  expect(extension.errors).toEqual([])
})
